#!/usr/bin/env python3
"""Regenerate reference/limits.md from scripts/tad/limits.py and styles.py.

Run after changing any limit, edge type, container type or shape, so the docs
always match what the checker enforces.
"""
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

from tad import limits as L  # noqa: E402
from tad import styles as S  # noqa: E402


def main():
    o = ["# Limits and vocabulary", "",
         "Generated by `scripts/gen_reference.py` from `scripts/tad/limits.py` and `scripts/tad/styles.py`.",
         "Do not edit by hand. `python3 scripts/make_tad.py --limits` prints the same table.", "",
         "Boxes grow to fit their text, so these limits do not depend on the layout.", "",
         "## Enforced limits", "", "| Limit | Value | Applies to |", "|---|---|---|"]
    for name, val, meaning in L.as_table():
        o.append(f"| `{name}` | {val} | {meaning} |")
    o += ["", "## Kinds", "", "| Kind | Default direction | Default node shape | Default container type |",
          "|---|---|---|---|"]
    for k in S.KINDS:
        o.append(f"| `{k}` | {S.DEFAULT_DIRECTION[k]} | {S.DEFAULT_SHAPE[k]} | {S.DEFAULT_CONTAINER_TYPE[k]} |")
    o += ["", "`AUTO` lays the view out left-to-right and top-down and keeps the one closer to a landscape page. "
          "When most ports have fixed east/west sides it uses RIGHT only; mostly north/south, DOWN only.", "",
          "## Edge types by kind", ""]
    for k in S.KINDS:
        o += [f"### {k}", "", "| Type | Legend text | Line | Start | End |", "|---|---|---|---|---|"]
        for n, v in S.EDGE_TYPES[k].items():
            o.append(f"| `{n}` | {v['label']} | {v['dash']} | {v['start']} | {v['end']} |")
        o += ["", f"Default type: `{S.DEFAULT_EDGE_TYPE[k]}`.", ""]
    o += ["## Container types", "", "| Type | Legend text | Line | Counts as a boundary (dataflow) |",
          "|---|---|---|---|"]
    for n, v in S.CONTAINER_TYPES.items():
        o.append(f"| `{n}` | {v['label']} | {v['dash']} | {'yes' if n in S.BOUNDARY_TYPES else ''} |")
    o += ["", "## Node shapes", "", ", ".join(f"`{s}`" for s in S.NODE_SHAPES), "",
          "Aliases: " + ", ".join(f"`{a}` -> `{b}`" for a, b in S.SHAPE_ALIASES.items()), "",
          "## Markings", "", "Banner colours for recognised markings (anything after `//` is kept as written):", "",
          "| Marking | Banner | Portion mark |", "|---|---|---|"]
    for m, (bg, fg) in S.MARKINGS.items():
        o.append(f"| {m} | #{bg} | {S.portion_mark(m)} |")
    o += ["", "The tool draws markings exactly as supplied. It does not determine or validate classification.", "",
          "## Page sizes (px, landscape)", "", "| Page | Size |", "|---|---|"]
    for n, v in S.PAGE_SIZES.items():
        o.append(f"| `{n}` | {'fit to content' if v is None else f'{v[0]} x {v[1]}'} |")
    path = os.path.join(os.path.dirname(HERE), "reference", "limits.md")
    with open(path, "w", encoding="utf-8") as f:
        f.write("\n".join(o) + "\n")
    print(f"wrote {path}")


if __name__ == "__main__":
    main()
